class Solution {
    int gcd(int a, int b) {
        while (b) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
public:
    long long countPairs(vector<int>& nums, int k) {
        vector<int> divs;
        for (int d = 1; d * d <= k; d++) {
            if (k % d == 0) {
                divs.push_back(d);
                if (d != k / d) divs.push_back(k / d);
            }
        }
        unordered_map<int, int> cnt;
        long long ans = 0;
        for (int x : nums) {
            int g = gcd(x, k);
            int need = k / g;
            for (int d : divs) {
                if (d % need == 0) {
                    ans += cnt[d];
                }
            }
            cnt[g]++;
        }
        return ans;
    }
};
